import json
import math
import os
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from urllib.parse import urlencode
from urllib.request import urlopen

ctx = (_items or [{"json": {}}])[0].get("json", {})
run_id = ctx.get("run_id") or ""
as_of = ctx.get("as_of") or datetime.now(timezone.utc).isoformat()
fred_key = ctx.get("fred_api_key") or os.getenv("FRED_API_KEY") or ""
timeout = min(4, max(2, int(ctx.get("macro_fetch_timeout_seconds") or 4)))
fetch_budget_seconds = min(50, max(10, int(ctx.get("macro_fetch_budget_seconds") or os.getenv("AG3_FX_MACRO_FETCH_BUDGET_SECONDS") or 45)))
max_workers = min(16, max(4, int(ctx.get("macro_fetch_max_workers") or os.getenv("AG3_FX_MACRO_FETCH_MAX_WORKERS") or 12)))
deadline = time.monotonic() + fetch_budget_seconds
currencies = ctx.get("currencies") or ["USD", "EUR", "JPY", "GBP", "CHF", "AUD", "CAD", "NZD"]

FRED_SERIES = {
    "USD": {
        "policy_rate": ("FEDFUNDS", True, 1.0),
        "inflation": ("CPIAUCSL", False, 0.8),
        "labor": ("UNRATE", False, 0.8),
    },
}
CURRENCY_COUNTRY = {
    "USD": "USA",
    "EUR": "EMU",
    "JPY": "JPN",
    "GBP": "GBR",
    "CHF": "CHE",
    "AUD": "AUS",
    "CAD": "CAN",
    "NZD": "NZL",
}
CURRENCY_COUNTRY_FALLBACKS = {
    "EUR": ["EMU", "EUU"],
}
EUR_MEMBER_PROXY_COUNTRIES = ["DEU", "FRA", "ITA", "ESP", "NLD"]
WORLDBANK_SERIES = {
    # World Bank does not expose central-bank policy rates consistently. This
    # proxy keeps AG3 from dropping the monetary component entirely when FRED or
    # official central-bank APIs are unavailable.
    "policy_rate": ("FR.INR.LEND", True, 0.7),
    "real_yield": ("FR.INR.RINR", True, 1.0),
    "inflation": ("FP.CPI.TOTL.ZG", False, 0.8),
    "growth": ("NY.GDP.MKTP.KD.ZG", True, 0.8),
    "labor": ("SL.UEM.TOTL.ZS", False, 0.6),
    "external_balance": ("BN.CAB.XOKA.GD.ZS", True, 0.5),
}

FACTOR_DEFAULTS = {
    "policy_rate": {"source": "FRED", "higher_is_bullish": True, "weight": 1.0},
    "real_yield": {"source": "FRED", "higher_is_bullish": True, "weight": 1.0},
    "inflation": {"source": "FRED", "higher_is_bullish": False, "weight": 0.8},
    "growth": {"source": "FRED", "higher_is_bullish": True, "weight": 0.8},
    "labor": {"source": "FRED", "higher_is_bullish": False, "weight": 0.6},
    "external_balance": {"source": "WorldBank", "higher_is_bullish": True, "weight": 0.5},
}


def clamp(v, lo=-1.0, hi=1.0):
    try:
        n = float(v)
        if not math.isfinite(n):
            return None
        return max(lo, min(hi, n))
    except Exception:
        return None


def remaining_timeout():
    remaining = deadline - time.monotonic()
    if remaining <= 0:
        raise TimeoutError("macro fetch budget exhausted")
    return max(1, min(timeout, remaining))


def fred_observations(series_id):
    if not fred_key:
        return []
    params = {
        "series_id": series_id,
        "api_key": fred_key,
        "file_type": "json",
        "sort_order": "desc",
        "limit": 18,
    }
    url = "https://api.stlouisfed.org/fred/series/observations?" + urlencode(params)
    with urlopen(url, timeout=remaining_timeout()) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
    out = []
    for row in payload.get("observations") or []:
        value = row.get("value")
        if value in (None, "."):
            continue
        try:
            out.append({"date": row.get("date"), "value": float(value)})
        except Exception:
            continue
    return out


def worldbank_observations(country, indicator):
    params = {"format": "json", "per_page": 20}
    url = f"https://api.worldbank.org/v2/country/{country}/indicator/{indicator}?" + urlencode(params)
    last_exc = None
    for _ in range(1):
        try:
            with urlopen(url, timeout=remaining_timeout()) as resp:
                payload = json.loads(resp.read().decode("utf-8"))
            break
        except Exception as exc:
            last_exc = exc
    else:
        raise last_exc
    rows = payload[1] if isinstance(payload, list) and len(payload) > 1 else []
    out = []
    for row in rows:
        value = row.get("value")
        if value is None:
            continue
        try:
            out.append({"date": str(row.get("date") or ""), "value": float(value)})
        except Exception:
            continue
    return out


def worldbank_member_proxy_observations(countries, indicator, min_members=3):
    by_year = {}
    for country in countries:
        if time.monotonic() >= deadline:
            break
        try:
            for row in worldbank_observations(country, indicator):
                year = str(row.get("date") or "")
                by_year.setdefault(year, []).append(row["value"])
        except Exception:
            continue
    out = []
    for year, values in by_year.items():
        if len(values) >= min_members:
            out.append({"date": year, "value": sum(values) / len(values)})
    return sorted(out, key=lambda x: str(x.get("date") or ""), reverse=True)


def zscore_normalized(obs, higher_is_bullish=True):
    values = [x["value"] for x in obs if x.get("value") is not None]
    if len(values) < 4:
        return None
    latest = values[0]
    sample = values[:10]
    mean = sum(sample) / len(sample)
    var = sum((x - mean) ** 2 for x in sample) / len(sample)
    sd = math.sqrt(var)
    if sd <= 0:
        return 0.0
    z = (latest - mean) / sd
    if not higher_is_bullish:
        z *= -1
    return clamp(z / 2.0)


def observation(currency, factor, source, series_id, value, previous, status, higher_is_bullish=True, weight=1.0, normalized_override=None):
    delta_1m = value - previous if value is not None and previous is not None else None
    raw = None
    if delta_1m is not None:
        scale = max(abs(previous or 0.0), 1.0)
        raw = delta_1m / scale
        if not higher_is_bullish:
            raw *= -1
    normalized = normalized_override if normalized_override is not None else (clamp((raw or 0.0) * 6.0) if status == "OK" else None)
    return {
        "observation_id": f"{run_id}_{currency}_{factor}",
        "run_id": run_id,
        "currency": currency,
        "factor": factor,
        "source": source,
        "series_id": series_id,
        "observation_date": None,
        "value": value,
        "previous_value": previous,
        "delta_1m": delta_1m,
        "delta_3m": None,
        "delta_12m": None,
        "zscore": None,
        "normalized_score": normalized,
        "weight": weight,
        "higher_is_bullish": bool(higher_is_bullish),
        "data_status": status,
        "fetched_at": as_of,
    }


def worldbank_record(currency, factor, indicator, higher_is_bullish, weight):
    countries = CURRENCY_COUNTRY_FALLBACKS.get(currency) or [CURRENCY_COUNTRY[currency]]
    obs = []
    country_used = countries[0]
    for country in countries:
        obs = worldbank_observations(country, indicator)
        country_used = country
        if obs:
            break
    if not obs and currency == "EUR":
        obs = worldbank_member_proxy_observations(EUR_MEMBER_PROXY_COUNTRIES, indicator)
        if obs:
            country_used = "EUR_PROXY_DEU_FRA_ITA_ESP_NLD"
    latest = obs[0] if obs else None
    previous = obs[1] if len(obs) > 1 else None
    norm = zscore_normalized(obs, higher_is_bullish=higher_is_bullish)
    status = "MISSING"
    if latest:
        try:
            year = int(str(latest.get("date") or "")[:4])
            current_year = int(str(as_of)[:4])
            status = "STALE" if year < current_year - 3 else "OK"
        except Exception:
            status = "OK"
    rec = observation(
        currency,
        factor,
        "WorldBankProxy" if factor == "policy_rate" else "WorldBank",
        f"{country_used}:{indicator}",
        latest.get("value") if latest else None,
        previous.get("value") if previous else None,
        status,
        higher_is_bullish,
        weight,
        normalized_override=norm if status == "OK" else None,
    )
    rec["observation_date"] = f"{latest.get('date')}-12-31" if latest else None
    return rec


observations = []
fetch_errors = []


def fetch_factor_record(ccy, factor, meta):
    configured = FRED_SERIES.get(ccy, {})
    if factor in configured:
        series_id, higher_is_bullish, weight = configured[factor]
        try:
            obs = fred_observations(series_id)
            latest = obs[0] if obs else None
            previous = obs[1] if len(obs) > 1 else None
            if latest:
                rec = observation(
                    ccy,
                    factor,
                    meta["source"],
                    series_id,
                    latest.get("value"),
                    previous.get("value") if previous else None,
                    "OK",
                    higher_is_bullish,
                    weight,
                )
                rec["observation_date"] = latest.get("date")
            elif factor in WORLDBANK_SERIES and ccy in CURRENCY_COUNTRY:
                indicator, wb_higher_is_bullish, wb_weight = WORLDBANK_SERIES[factor]
                rec = worldbank_record(ccy, factor, indicator, wb_higher_is_bullish, wb_weight)
            else:
                rec = observation(ccy, factor, meta["source"], series_id, None, None, "MISSING", higher_is_bullish, weight)
            return rec, None
        except Exception as exc:
            return (
                observation(ccy, factor, meta["source"], series_id, None, None, "ERROR", meta["higher_is_bullish"], meta["weight"]),
                f"{ccy}.{factor}.{series_id}: {exc}",
            )
    if factor in WORLDBANK_SERIES and ccy in CURRENCY_COUNTRY:
        indicator, higher_is_bullish, weight = WORLDBANK_SERIES[factor]
        try:
            return worldbank_record(ccy, factor, indicator, higher_is_bullish, weight), None
        except Exception as exc:
            source = "WorldBankProxy" if factor == "policy_rate" else "WorldBank"
            return (
                observation(ccy, factor, source, indicator, None, None, "ERROR", higher_is_bullish, weight),
                f"{ccy}.{factor}.{indicator}: {exc}",
            )
    return observation(ccy, factor, meta["source"], None, None, None, "NOT_MAPPED", meta["higher_is_bullish"], meta["weight"]), None


tasks = [(ccy, factor, meta) for ccy in currencies for factor, meta in FACTOR_DEFAULTS.items()]
results_by_key = {}
executor = ThreadPoolExecutor(max_workers=max_workers)
future_map = {executor.submit(fetch_factor_record, ccy, factor, meta): (ccy, factor, meta) for ccy, factor, meta in tasks}
try:
    for future in as_completed(future_map, timeout=fetch_budget_seconds):
        ccy, factor, meta = future_map[future]
        try:
            rec, err = future.result()
        except Exception as exc:
            rec = observation(ccy, factor, meta["source"], None, None, None, "ERROR", meta["higher_is_bullish"], meta["weight"])
            err = f"{ccy}.{factor}: {exc}"
        results_by_key[(ccy, factor)] = rec
        if err:
            fetch_errors.append(err)
except Exception as exc:
    fetch_errors.append(f"macro_fetch_budget_exhausted: {exc}")
finally:
    executor.shutdown(wait=False, cancel_futures=True)

for ccy, factor, meta in tasks:
    rec = results_by_key.get((ccy, factor))
    if rec is None:
        rec = observation(ccy, factor, meta["source"], None, None, None, "ERROR", meta["higher_is_bullish"], meta["weight"])
        fetch_errors.append(f"{ccy}.{factor}: macro fetch budget exhausted")
    observations.append(rec)

ok_count = sum(1 for x in observations if x.get("data_status") == "OK")
status_by_currency = {ccy: {} for ccy in currencies}
for row in observations:
    ccy = str(row.get("currency") or "").upper()
    factor = str(row.get("factor") or "")
    if ccy in status_by_currency and factor:
        status_by_currency[ccy][factor] = str(row.get("data_status") or "").upper()

critical_factors = {"policy_rate", "real_yield"}
critical_ok_count = sum(
    1
    for ccy in currencies
    for factor in critical_factors
    if status_by_currency.get(ccy, {}).get(factor) == "OK"
)
currency_ok_count = sum(
    1
    for ccy in currencies
    if sum(1 for status in status_by_currency.get(ccy, {}).values() if status == "OK") >= 4
)
critical_coverage = critical_ok_count / max(1, len(currencies) * len(critical_factors))
currency_coverage = currency_ok_count / max(1, len(currencies))
macro_data_degraded = (
    ok_count < max(3, len(currencies) * 3)
    or critical_coverage < 0.50
    or currency_coverage < 0.75
)
macro_quality = {
    "ok_count": ok_count,
    "total_observations": len(observations),
    "critical_ok_count": critical_ok_count,
    "critical_total": len(currencies) * len(critical_factors),
    "critical_coverage": critical_coverage,
    "currency_ok_count": currency_ok_count,
    "currency_total": len(currencies),
    "currency_coverage": currency_coverage,
    "degraded_reasons": [],
}
if ok_count < max(3, len(currencies) * 3):
    macro_quality["degraded_reasons"].append("LOW_TOTAL_MACRO_COVERAGE")
if critical_coverage < 0.50:
    macro_quality["degraded_reasons"].append("LOW_POLICY_RATE_REAL_YIELD_COVERAGE")
if currency_coverage < 0.75:
    macro_quality["degraded_reasons"].append("LOW_CURRENCY_FACTOR_COVERAGE")

return [{
    "json": {
        **ctx,
        "macro_observations": observations,
        "macro_observation_ok_count": ok_count,
        "macro_quality": macro_quality,
        "macro_fetch_errors": fetch_errors,
        "macro_data_degraded": macro_data_degraded,
    }
}]

import json
import math
from datetime import datetime, timezone

ctx = (_items or [{"json": {}}])[0].get("json", {})
run_id = ctx.get("run_id") or ""
as_of = ctx.get("as_of") or datetime.now(timezone.utc).isoformat()
currencies = ctx.get("currencies") or ["USD", "EUR", "JPY", "GBP", "CHF", "AUD", "CAD", "NZD"]
macro_news = ctx.get("macro_news") or {}
macro_regime = macro_news.get("macro_regime") or {}
pair_focus = macro_news.get("pair_focus") or {}
observations = ctx.get("macro_observations") or []
macro_data_degraded = bool(ctx.get("macro_data_degraded"))

WEIGHTS = {
    "monetary_score": 0.30,
    "real_yield_score": 0.20,
    "inflation_score": 0.10,
    "growth_score": 0.15,
    "labor_score": 0.05,
    "external_balance_score": 0.10,
    "risk_regime_score": 0.10,
}
FACTOR_TO_COMPONENT = {
    "policy_rate": "monetary_score",
    "central_bank_bias": "monetary_score",
    "real_yield": "real_yield_score",
    "inflation": "inflation_score",
    "growth": "growth_score",
    "labor": "labor_score",
    "external_balance": "external_balance_score",
}
SAFE_HAVENS = {"USD", "JPY", "CHF"}
CYCLICALS = {"AUD", "NZD"}
OIL_LINKED = {"CAD"}


def clamp(v, lo=-1.0, hi=1.0):
    try:
        n = float(v)
        if not math.isfinite(n):
            return 0.0
        return max(lo, min(hi, n))
    except Exception:
        return 0.0


def to_float(v, default=0.0):
    try:
        n = float(v)
        return n if math.isfinite(n) else default
    except Exception:
        return default


def avg(values):
    clean = [to_float(x) for x in values if x is not None]
    return clamp(sum(clean) / len(clean)) if clean else 0.0


def parse_bias_value(value):
    if isinstance(value, (int, float)):
        return clamp(value)
    if isinstance(value, dict):
        for key in ("score", "bias_score", "value"):
            if key in value:
                return clamp(value.get(key))
        value = value.get("bias") or value.get("direction") or value.get("label") or ""
    text = str(value or "").lower()
    if any(x in text for x in ("strong_bull", "very bullish", "bullish")):
        return 0.45
    if any(x in text for x in ("strong_bear", "very bearish", "bearish")):
        return -0.45
    return 0.0


def signed_label_score(label, pair, raw_score):
    pair = str(pair or "").upper()
    base, quote = pair[:3], pair[3:]
    text = str(label or "").strip().lower()
    magnitude = abs(to_float(raw_score, 0.0))
    if magnitude <= 0:
        magnitude = 0.35
    magnitude = min(1.0, magnitude)

    signs = {}
    bullish = "bullish" in text or text in {"buy_base", "long_base", "buy", "long"}
    bearish = "bearish" in text or text in {"sell_base", "short_base", "sell", "short"}

    for ccy in currencies:
        c = ccy.lower()
        if c not in text:
            continue
        if bullish:
            signs[ccy] = 1.0
        elif bearish:
            signs[ccy] = -1.0

    if not signs and base and quote:
        if text in {"buy_base", "long_base", "bullish", "buy", "long"}:
            signs[base] = 1.0
            signs[quote] = -1.0
        elif text in {"sell_base", "short_base", "bearish", "sell", "short"}:
            signs[base] = -1.0
            signs[quote] = 1.0

    # When AG4 names only one side of a pair, infer a smaller opposite vote for
    # the other side. This keeps pair-specific news directional in degraded mode
    # without pretending it is a full independent macro observation.
    if base in signs and quote and quote not in signs:
        signs[quote] = -0.65 * signs[base]
    if quote in signs and base and base not in signs:
        signs[base] = -0.65 * signs[quote]

    return {ccy: clamp(sign * magnitude) for ccy, sign in signs.items()}


def macro_biases():
    raw = macro_regime.get("biases") or macro_regime.get("currency_biases") or {}
    out = {ccy: 0.0 for ccy in currencies}
    if isinstance(raw, dict):
        for ccy, value in raw.items():
            key = str(ccy or "").upper()
            if key in out:
                out[key] = parse_bias_value(value)
    return out


def pair_focus_votes():
    votes = {ccy: [] for ccy in currencies}
    for pair, focus in (pair_focus or {}).items():
        pair = str(pair or "").upper()
        if len(pair) != 6 or not isinstance(focus, dict):
            continue
        confidence = max(0.1, min(1.0, to_float(focus.get("confidence"), 0.35)))
        label = focus.get("bias_news") or focus.get("bias") or ""
        signed = signed_label_score(label, pair, focus.get("bias_news_score"))
        for ccy, score in signed.items():
            if ccy in votes:
                votes[ccy].append(score * confidence)
    return {ccy: avg(vals) for ccy, vals in votes.items()}


def regime_score(ccy):
    label = str(macro_regime.get("market_regime") or macro_regime.get("regime") or "").lower()
    if "risk-off" in label or "risk_off" in label or "stress" in label:
        if ccy in SAFE_HAVENS:
            return 0.35
        if ccy in OIL_LINKED:
            return 0.05
        if ccy in CYCLICALS:
            return -0.30
        return -0.08
    if "risk-on" in label or "risk_on" in label:
        if ccy in SAFE_HAVENS:
            return -0.25
        if ccy in CYCLICALS:
            return 0.30
        return 0.08
    return 0.0


OBSERVABLE_FACTORS = {"policy_rate", "real_yield", "inflation", "growth", "labor", "external_balance"}
grouped = {ccy: {} for ccy in currencies}
missing = {ccy: set(OBSERVABLE_FACTORS) for ccy in currencies}
stale = {ccy: set() for ccy in currencies}

for obs in observations:
    ccy = str(obs.get("currency") or "").upper()
    factor = str(obs.get("factor") or "")
    component = FACTOR_TO_COMPONENT.get(factor)
    if ccy not in grouped or not component:
        continue
    status = str(obs.get("data_status") or "").upper()
    if status == "OK":
        grouped[ccy].setdefault(component, []).append(obs.get("normalized_score"))
        missing[ccy].discard(factor)
    elif status in {"STALE", "ERROR"}:
        stale[ccy].add(factor)

regime_bias = macro_biases()
news_votes = pair_focus_votes()
scores = []

for ccy in currencies:
    components = {
        "monetary_score": avg(grouped[ccy].get("monetary_score", [])),
        "real_yield_score": avg(grouped[ccy].get("real_yield_score", [])),
        "inflation_score": avg(grouped[ccy].get("inflation_score", [])),
        "growth_score": avg(grouped[ccy].get("growth_score", [])),
        "labor_score": avg(grouped[ccy].get("labor_score", [])),
        "external_balance_score": avg(grouped[ccy].get("external_balance_score", [])),
        "risk_regime_score": clamp(0.35 * regime_score(ccy) + 0.35 * regime_bias.get(ccy, 0.0) + 0.30 * news_votes.get(ccy, 0.0)),
    }
    news_bias_score = clamp(0.70 * news_votes.get(ccy, 0.0) + 0.30 * regime_bias.get(ccy, 0.0))
    model_composite = clamp(sum(components[k] * w for k, w in WEIGHTS.items()))
    if macro_data_degraded:
        composite = clamp(0.55 * news_bias_score + 0.45 * components["risk_regime_score"])
    else:
        composite = clamp(0.85 * model_composite + 0.15 * news_bias_score)
    ok_components = sum(1 for k in components if abs(components[k]) > 0.00001 and k != "risk_regime_score")
    usable_components = sum(
        1
        for factor, component in FACTOR_TO_COMPONENT.items()
        if component in grouped[ccy] and grouped[ccy].get(component)
    )
    data_quality = max(0.10, min(1.0, (usable_components / 6.0) * 0.75 + 0.25 * (1.0 if macro_news else 0.0)))
    critical_missing = bool({"policy_rate", "real_yield"} & (missing[ccy] | stale[ccy]))
    if critical_missing:
        data_quality = min(data_quality, 0.65)
    if macro_data_degraded:
        data_quality = min(data_quality, 0.55)
    confidence = max(0.20, min(0.90, 0.30 + 0.45 * data_quality + 0.15 * abs(composite) + 0.10 * min(1.0, ok_components / 6.0)))
    if macro_data_degraded:
        confidence = min(confidence, 0.45)
    rationale_bits = []
    if components["risk_regime_score"] > 0.10:
        rationale_bits.append(f"{ccy} supported by current risk/news regime")
    elif components["risk_regime_score"] < -0.10:
        rationale_bits.append(f"{ccy} pressured by current risk/news regime")
    if abs(news_bias_score) > 0.10:
        rationale_bits.append(f"{ccy} news proxy {'bullish' if news_bias_score > 0 else 'bearish'}")
    if not rationale_bits:
        rationale_bits.append(f"{ccy} fundamental inputs mostly neutral or unavailable")

    scores.append({
        "score_id": f"{run_id}_{ccy}",
        "run_id": run_id,
        "currency": ccy,
        "as_of": as_of,
        **components,
        "news_bias_score": news_bias_score,
        "composite_score": composite,
        "confidence": confidence,
        "data_quality_score": data_quality,
        "missing_factors": json.dumps(sorted(missing[ccy])),
        "stale_factors": json.dumps(sorted(stale[ccy])),
        "rationale": "; ".join(rationale_bits),
    })

return [{"json": {**ctx, "currency_scores": scores, "currencies_scored": len(scores)}}]

import json
import math
from datetime import datetime, timezone

ctx = (_items or [{"json": {}}])[0].get("json", {})
run_id = ctx.get("run_id") or ""
as_of = ctx.get("as_of") or datetime.now(timezone.utc).isoformat()
universe = ctx.get("universe_fx") or []
technical = ctx.get("technical_signals") or []
macro_news = ctx.get("macro_news") or {}
pair_focus = macro_news.get("pair_focus") or {}
macro_regime = macro_news.get("macro_regime") or {}
macro_data_degraded = bool(ctx.get("macro_data_degraded"))
currency_scores = {str(x.get("currency") or "").upper(): x for x in (ctx.get("currency_scores") or [])}
tech_by_pair = {str(x.get("pair") or "").upper(): x for x in technical}


def clamp(v, lo=-1.0, hi=1.0):
    try:
        n = float(v)
        if not math.isfinite(n):
            return 0.0
        return max(lo, min(hi, n))
    except Exception:
        return 0.0


def to_float(v, default=0.0):
    try:
        n = float(v)
        return n if math.isfinite(n) else default
    except Exception:
        return default


def direct_pair_news_score(pair, label, raw_score):
    pair = str(pair or "").upper()
    base, quote = pair[:3], pair[3:]
    text = str(label or "").strip().lower()
    magnitude = abs(to_float(raw_score, 0.0))
    if magnitude <= 0:
        magnitude = 0.35
    magnitude = min(1.0, magnitude)

    if text in {"buy_base", "long_base", "bullish", "buy", "long"}:
        return magnitude
    if text in {"sell_base", "short_base", "bearish", "sell", "short"}:
        return -magnitude

    if base.lower() in text:
        if "bullish" in text:
            return magnitude
        if "bearish" in text:
            return -magnitude
    if quote.lower() in text:
        if "bullish" in text:
            return -magnitude
        if "bearish" in text:
            return magnitude
    return 0.0


def pair_news(pair):
    f = pair_focus.get(pair) or {}
    label = str(f.get("bias_news") or f.get("bias") or "unknown")
    conf = to_float(f.get("confidence"), 0.0)
    urgent = bool(f.get("urgent_event_within_4h"))
    score = direct_pair_news_score(pair, label, f.get("bias_news_score"))
    drivers = f.get("top_drivers") or []
    if not isinstance(drivers, list):
        drivers = [str(drivers)]
    return label, conf, urgent, score, drivers


def directional_bias(pressure):
    if pressure >= 0.25:
        return "BUY_BASE"
    if pressure <= -0.25:
        return "SELL_BASE"
    return "NEUTRAL"


def sign(v):
    n = to_float(v, 0.0)
    if n > 0.08:
        return 1
    if n < -0.08:
        return -1
    return 0


def conflict_score(base_score, quote_score, relative_pressure, direct_news_score):
    same_side = 0.0
    if sign(base_score) and sign(base_score) == sign(quote_score):
        same_side = min(abs(to_float(base_score)), abs(to_float(quote_score)), 1.0)
    directional = 0.0
    if abs(to_float(relative_pressure)) > 0.15 and abs(to_float(direct_news_score)) > 0.15:
        if sign(relative_pressure) and sign(relative_pressure) != sign(direct_news_score):
            directional = min(abs(to_float(relative_pressure)), abs(to_float(direct_news_score)), 1.0)
    return clamp(max(same_side, directional), 0.0, 1.0)


def macro_currency_bias(ccy):
    raw = macro_regime.get("biases") or macro_regime.get("currency_biases") or {}
    if isinstance(raw, dict):
        return clamp(raw.get(ccy))
    return 0.0


def invalidators(pair, base, quote, bias):
    if bias == "BUY_BASE":
        return [
            f"{base} dovish repricing or weak growth surprise",
            f"{quote} hawkish repricing or positive inflation surprise",
            f"Fresh AG4-FX urgent event reversing {pair} macro direction",
        ]
    if bias == "SELL_BASE":
        return [
            f"{base} hawkish repricing or positive inflation surprise",
            f"{quote} dovish repricing or weak growth surprise",
            f"Fresh AG4-FX urgent event reversing {pair} macro direction",
        ]
    return [
        "Clear central-bank repricing on either currency",
        "Urgent macro/news event creating directional asymmetry",
        "Large risk-regime shift not reflected in current digest",
    ]


pairs = []
for row in universe:
    pair = str(row.get("pair") or "").upper()
    base = str(row.get("base_ccy") or pair[:3]).upper()
    quote = str(row.get("quote_ccy") or pair[3:]).upper()
    if not pair or len(pair) != 6:
        continue
    base_rec = currency_scores.get(base, {})
    quote_rec = currency_scores.get(quote, {})
    base_score = clamp(base_rec.get("composite_score"))
    quote_score = clamp(quote_rec.get("composite_score"))
    relative_pressure = clamp(base_score - quote_score)
    tech = tech_by_pair.get(pair) or {}
    news_label, news_conf, urgent, direct_news_score, news_drivers = pair_news(pair)
    direct_weight = 0.25 if macro_data_degraded else 0.15
    pair_pressure = clamp((1.0 - direct_weight) * relative_pressure + direct_weight * direct_news_score)
    pair_conflict_score = conflict_score(base_score, quote_score, relative_pressure, direct_news_score)
    base_macro_bias = macro_currency_bias(base)
    quote_macro_bias = macro_currency_bias(quote)
    if sign(base_macro_bias) and sign(base_macro_bias) == sign(quote_macro_bias):
        pair_conflict_score = max(pair_conflict_score, min(abs(base_macro_bias), abs(quote_macro_bias), 1.0))
    if pair_conflict_score >= 0.10:
        pair_pressure = clamp(pair_pressure * (1.0 - min(0.35, pair_conflict_score)))
    pair_score = pair_pressure
    bias = directional_bias(pair_pressure)
    confidence = min(
        to_float(base_rec.get("confidence"), 0.25),
        to_float(quote_rec.get("confidence"), 0.25),
    )
    if news_conf:
        confidence = min(0.95, confidence * 0.75 + news_conf * 0.25)
    if urgent:
        confidence = max(confidence, min(0.80, news_conf + 0.10))
    if macro_data_degraded:
        confidence = min(confidence, 0.45)
    if pair_conflict_score >= 0.10:
        confidence = max(0.20, confidence * (1.0 - min(0.30, pair_conflict_score)))
    data_quality = min(
        to_float(base_rec.get("data_quality_score"), 0.1),
        to_float(quote_rec.get("data_quality_score"), 0.1),
    )
    drivers = []
    for rec in (base_rec, quote_rec):
        text = rec.get("rationale")
        if text:
            drivers.extend([x.strip() for x in str(text).split(";") if x.strip()])
    drivers.extend([str(x) for x in news_drivers if str(x).strip()])
    if pair_conflict_score >= 0.10:
        drivers.append(
            f"{base}/{quote} has conflicting or same-direction currency support; size cautiously"
        )
    if not drivers:
        drivers = [f"{base}/{quote} relative fundamental pressure is neutral"]
    pairs.append({
        "score_id": f"{run_id}_{pair}",
        "run_id": run_id,
        "pair": pair,
        "symbol_yf": row.get("symbol_yf") or f"{pair}=X",
        "base_ccy": base,
        "quote_ccy": quote,
        "as_of": as_of,
        "spot": to_float(tech.get("last_close"), None),
        "base_score": base_score,
        "quote_score": quote_score,
        "pair_pressure": pair_pressure,
        "pair_score": pair_score,
        "directional_bias": bias,
        "confidence": confidence,
        "data_quality_score": data_quality,
        "macro_regime": str(macro_regime.get("market_regime") or macro_regime.get("regime") or "Unknown"),
        "news_bias": news_label,
        "news_confidence": news_conf,
        "news_direct_score": direct_news_score,
        "pair_conflict_score": pair_conflict_score,
        "rationale": json.dumps(drivers[:6], ensure_ascii=False),
        "invalidators": json.dumps(invalidators(pair, base, quote, bias), ensure_ascii=False),
    })

return [{"json": {**ctx, "pair_fundamental_scores": pairs, "pairs_scored": len(pairs)}}]
